<template><view class="page"><view class="card profile"><view class="avatar">{{ user?.nickname?.slice(0,1)||'游' }}</view><view class="page-title">{{ user?.nickname }}</view><view class="muted">账号：{{ user?.username }}</view><button class="secondary-btn" @click="edit">修改资料</button><button class="secondary-btn" @click="history">签到记录</button><button class="danger-btn" @click="logout">退出登录</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'@/services/api';import{refreshToken,requireSession}from'@/services/session';import{useSessionStore}from'@/stores/session';import type{User}from'@/services/types';const session=useSessionStore(),user=ref<User|null>(null);onShow(async()=>{if(!requireSession())return;user.value=await api('/users/me');uni.setStorageSync('tourism.user',user.value);session.reload()});const edit=()=>uni.navigateTo({url:'/pages/editInfo/editInfo'});const history=()=>uni.navigateTo({url:'/pages/signDetail/signDetail'});async function logout(){try{await api('/auth/logout','POST',{refreshToken:refreshToken()})}finally{session.clear();uni.reLaunch({url:'/pages/login/login'})}}</script><style scoped lang="scss">.profile{text-align:center;margin-top:8vh}.avatar{width:140rpx;height:140rpx;line-height:140rpx;border-radius:50%;margin:0 auto 24rpx;background:$primary;color:#fff;font-size:56rpx}</style>
